CREATE TABLE `chuyen_muc` (
  `id` bigint(20) NOT NULL,
  `ten` varchar(200) NOT NULL COMMENT 'Tên hiển thị: "Ba chương trình"',
  `slug` varchar(200) NOT NULL COMMENT 'Slug riêng cấp này: "ba-chuong-trinh"',
  `full_path_slug` varchar(1000) NOT NULL COMMENT 'Full path: "doan-thanh-nien/ba-chuong-trinh"',
  `duong_dan` varchar(1000) NOT NULL COMMENT 'Path ID dạng "1/2" — dùng LIKE query toàn subtree',
  `parent_id` bigint(20) DEFAULT NULL COMMENT 'NULL = node gốc; FK tự tham chiếu',
  `cap` int(11) NOT NULL DEFAULT 1 COMMENT 'Cấp node: 1, 2, 3...',
  `mo_ta` varchar(500) DEFAULT NULL,
  `mau_sac` varchar(20) DEFAULT NULL COMMENT 'Mã màu HEX: #0017B0',
  `icon` varchar(50) DEFAULT NULL COMMENT 'Tên icon Lucide React',
  `to_chuc` enum('BAN_DOI_CLB','CHUNG','DOAN','HOI') DEFAULT NULL,
  `ban_id` varchar(20) DEFAULT NULL COMMENT 'FK → ban.ma_ban nếu thuộc Ban/Đội/CLB cụ thể',
  `thu_tu` int(11) NOT NULL DEFAULT 0 COMMENT 'Thứ tự trong cùng cấp cha',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Danh mục bài viết — cây N cấp dùng Adjacency List';

--
