--
-- Cấu trúc bảng cho bảng `tin_tuc`
--

CREATE TABLE `tin_tuc` (
  `id` bigint(20) NOT NULL,
  `tieu_de` varchar(500) NOT NULL COMMENT 'Tiêu đề bài viết',
  `slug` varchar(500) NOT NULL COMMENT 'Slug sinh từ tiêu đề, max 80 ký tự',
  `full_url_path` varchar(1000) NOT NULL COMMENT 'Full path URL: "cat1/cat2/slug-bai"',
  `tom_tat` text DEFAULT NULL COMMENT 'Tóm tắt ≤ 300 ký tự, dùng cho SEO description',
  `noi_dung` longtext DEFAULT NULL COMMENT 'Nội dung HTML từ rich text editor',
  `anh_dai_dien` varchar(500) DEFAULT NULL COMMENT 'URL ảnh thumbnail / đại diện',
  `chuyen_muc_id` bigint(20) NOT NULL COMMENT 'FK → chuyen_muc.id (bắt buộc)',
  `van_ban_id` bigint(20) DEFAULT NULL COMMENT 'FK → van_ban.id (liên kết tùy chọn)',
  `hoat_dong_id` varchar(50) DEFAULT NULL COMMENT 'FK mềm → hoat_dong.ma_hoat_dong (enforce ở Service, TT-001)',
  `trang_thai` enum('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',
  `is_ghim` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Ghim lên đầu trang chủ',
  `nguoi_tao` varchar(50) NOT NULL COMMENT 'FK mềm → tai_khoan.username',
  `don_vi_dang` varchar(100) DEFAULT NULL COMMENT 'Tên đơn vị đăng: "Đoàn TN Trường ĐH Kiên Giang"',
  `luot_xem` int(11) NOT NULL DEFAULT 0,
  `ngay_xuat_ban` datetime DEFAULT NULL COMMENT 'Tự set = NOW() khi trang_thai → PUBLISHED (TT-002)',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `tac_gia` varchar(150) DEFAULT NULL,
  `ma_khoa` varchar(20) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bài đăng tin tức eNews';

--
-- Đang đổ dữ liệu cho bảng `tin_tuc`
--

INSERT INTO `tin_tuc` (`id`, `tieu_de`, `slug`, `full_url_path`, `tom_tat`, `noi_dung`, `anh_dai_dien`, `chuyen_muc_id`, `van_ban_id`, `hoat_dong_id`, `trang_thai`, `is_ghim`, `nguoi_tao`, `don_vi_dang`, `luot_xem`, `ngay_xuat_ban`, `is_deleted`, `created_at`, `updated_at`, `tac_gia`, `ma_khoa`) VALUES
(1, 'Đây là bài viết để test tính hoạt động', 'day-la-bai-viet-de-test-tinh-hoat-dong', 'doan-thanh-nien/tin-tuc-su-kien/day-la-bai-viet-de-test-tinh-hoat-dong', 'Ngắn gọn nhất có thể rồi', '<p>Đây là nội dung tôi chưa ưng</p><blockquote><img src=\"data:image/jpeg;base64,\"></blockquote><blockquote><br></blockquote>', '', 10, NULL, NULL, 'PUBLISHED', 0, 'admin', NULL, 0, '2026-03-01 11:54:44', 1, '2026-02-28 10:52:21', '2026-03-01 12:02:52', NULL, NULL);
INSERT INTO `tin_tuc` (`id`, `tieu_de`, `slug`, `full_url_path`, `tom_tat`, `noi_dung`, `anh_dai_dien`, `chuyen_muc_id`, `van_ban_id`, `hoat_dong_id`, `trang_thai`, `is_ghim`, `nguoi_tao`, `don_vi_dang`, `luot_xem`, `ngay_xuat_ban`, `is_deleted`, `created_at`, `updated_at`, `tac_gia`, `ma_khoa`) VALUES
(2, 'ĐÂY LÀ TEST ĐÓ NHA TRỜI', 'day-la-test-do-nha-troi', 'doan-thanh-nien/hoi-nhap-quoc-te/day-la-test-do-nha-troi', 'TÓm ấtda', '<blockquote><p>Đây là một cái gì đó để test thôi</p></blockquote><p><span>cỳytyt</span><span style=\"color: rgb(240, 102, 102);\">ftyfty</span></p>', '', 14, NULL, 'KH012ĐTN2026', 'PUBLISHED', 0, 'admin', '', 0, '2026-03-01 11:54:56', 1, '2026-03-01 00:00:36', '2026-03-01 12:02:56', NULL, NULL),
(3, 'TEST BÀI VIẾT SỐ 3', 'test-bai-viet-so-3', 'doan-thanh-nien/ba-phong-trao/test-bai-viet-so-3', '', '<table class=\"editor-table border-collapse w-full my-6\" style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: center;\">HỘI SINH VIÊN TRƯỜNG ĐẠI HỌC KIÊN GIANG</p><p style=\"text-align: center;\"></p><img class=\"editor-image shadow-md rounded-lg max-w-full h-auto mx-auto my-6 block\" src=\"file:///C:/Users/thanh/AppData/Local/Temp/msohtmlclip1/01/clip_image001.png\" width=\"291\" height=\"1\"><p><strong>CÂU LẠC BỘ TRUYỀN THÔNG VÀ MÁY TÍNH</strong></p><p style=\"text-align: center;\"><strong>&nbsp;</strong></p><p style=\"text-align: center;\">Số:…./KH-CLBTTMT</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: center;\"><strong>&nbsp;</strong></p><p style=\"text-align: center;\"><strong>&nbsp;</strong></p><p style=\"text-align: center;\"><strong>&nbsp;</strong></p><p style=\"text-align: center;\"><em>An Giang, &nbsp;&nbsp;&nbsp;&nbsp;ngày&nbsp; &nbsp;&nbsp;&nbsp;tháng&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;năm &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</em></p></td></tr></tbody></table><p>&nbsp;</p><p style=\"text-align: center;\"><strong>KẾ HOẠCH</strong></p><p style=\"text-align: center;\"><strong>Tổ chức Giải thi đấu Thể thao điện tử năm học 2025-2026</strong></p><p style=\"text-align: center;\"><strong>Chào mừng thành công Đại hội Đoàn thanh niên Tỉnh An Giang lần 1 và</strong></p><p style=\"text-align: center;\"><strong>Chào mừng 76 năm Ngày Truyền thống Học sinh – Sinh viên</strong></p><p style=\"text-align: center;\"><strong>và Hội sinh viên Việt Nam (09/01/1950 – 09/01/2026)</strong></p><p style=\"text-align: center;\"></p><table class=\"editor-table border-collapse w-full my-6\" style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p></p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><img class=\"editor-image shadow-md rounded-lg max-w-full h-auto mx-auto my-6 block\" src=\"file:///C:/Users/thanh/AppData/Local/Temp/msohtmlclip1/01/clip_image002.png\" width=\"188\" height=\"1\"></td></tr></tbody></table><p>&nbsp;</p><p></p><p><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>I. MỤC ĐÍCH - YÊU CẦU</strong></p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Chào mừng thành công Đại hội Đoàn Thanh niên Tỉnh An Giang lần I nhiệm kỳ 2025 – 2030 và chào mừng 76 năm Ngày Truyền thống Học sinh – Sinh viên và Hội sinh viên Việt Nam (09/01/1950 – 09/01/206);</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Tạo ra một sân chơi lành mạnh, bổ ích và hiện đại, giúp đoàn viên, thanh niên, học sinh, sinh viên trong toàn tỉnh có cơ hội giao lưu, học hỏi, tăng cường tinh thần đoàn kết; đồng thời phát huy sở thích cá nhân, rèn luyện kỹ năng làm việc nhóm, tư duy chiến thuật và khả năng phản xạ nhanh nhạy thông qua bộ môn Thể thao điện tử (E-Sports).</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Đẩy mạnh phong trào văn hóa, văn nghệ, thể dục thể thao trong khối học sinh, sinh viên, góp phần nâng cao đời sống tinh thần và tạo động lực thực hiện thắng lợi nhiệm vụ năm học 2025-2026.</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Giải đấu phải được tổ chức chu đáo, nghiêm túc, công bằng, an toàn, tuân thủ đúng nội dung và thời gian quy định trong Kế hoạch, đảm bảo tính chuyên nghiệp của bộ môn Thể thao điện tử; nghiêm cấm tuyệt đối các hành vi tiêu cực, gian lận trong thi đấu và phải quản lý chặt chẽ nội dung truyền thông để đảm bảo tính giáo dục, định hướng lành mạnh cho người tham gia.</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>II. ĐỐI TƯỢNG THAM GIA VÀ MÔN THI ĐẤU</strong></p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>1. Đối tượng tham gia:</strong> Toàn thể đoàn viên, hội viên, thanh niên đang học tập tại Trường</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>2. Môn thi đấu</strong>: Liên quân Mobile (tên Tiếng Anh: Arena of Valor)</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>3. Thời gian và địa điểm</strong></p><table class=\"editor-table border-collapse w-full my-6\" style=\"min-width: 125px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">STT</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Nội dung</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Thời gian dự kiến</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Địa điểm</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Ghi chú</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">1</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Đăng ký tham gia</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Từ ngày ra Kế hoạch đến hết ngày …./1/2026</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Đăng ký trực tuyến tại website ……….</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">&nbsp;</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">2</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Bốc thăm và chia bảng đấu</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Ngày …/1/2026</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">[Địa điểm]</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Công bố lịch thi đấu</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">3</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Khai mạc giải đấu</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Ngày …./1/2026</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">[Địa điểm]</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">&nbsp;</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">4</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Thời gian thi đấu</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Từ ngày …/1/2026 đến ngày …/1/2026</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">[Địa điểm thi đấu]</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Lịch thi đấu chi tiết sẽ thông báo sau khi bốc thăm</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">5</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Chung kết và Bế mạc</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Ngày …./1/2026</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">[Địa điểm]</p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">Trao giải thưởng</p></td></tr></tbody></table><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>III. THỂ LỆ VÀ CƠ CẤU GIẢI THƯỞNG</strong></p><p style=\"text-align: justify;\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 1. Thể lệ và Luật thi đấu:</strong> Thể lệ và Luật thi đấu chi tiết sẽ được quy định cụ thể tại Phụ lục kèm theo Kế hoạch này.</p><p style=\"text-align: justify;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>2. Cơ cấu giải thưởng:</strong> Cơ cấu giải thưởng được áp dụng linh hoạt dựa trên số lượng đội đăng ký chính thức, nhằm khuyến khích sự tham gia của đông đảo đoàn viên, thanh niên.</p><p style=\"text-align: justify;\"><strong>Trường hợp huy động tối thiểu 6 đội thi đấu</strong></p><table class=\"editor-table border-collapse w-full my-6\" style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Hạng giải</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Chi tiết phần thưởng</strong></p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Nhất</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 02 TGG trị giá 600 QH</p><p style=\"text-align: justify;\">- 05 điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Nhì</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 01 TGG 400 QH</p><p style=\"text-align: justify;\">- 01 TGG 400 QH (áp dụng cho trang phục ≥ 499 QH)</p><p style=\"text-align: justify;\">- 03 điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Ba</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 01 TGG 200 QH</p><p style=\"text-align: justify;\">- 01 TGG 400 QH (áp dụng cho trang phục ≥ 499 QH)</p><p style=\"text-align: justify;\">- 02 điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Tư</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 01 TGG 100 QH</p><p style=\"text-align: justify;\">- 01 TGG 300 QH (áp dụng cho trang phục ≥499 QH)</p><p style=\"text-align: justify;\">- 01 điểm quay thưởng tại website của Garena</p></td></tr></tbody></table><p style=\"text-align: justify;\"><strong>Trường hợp huy động tối thiểu 16 đội thi đấu</strong></p><table class=\"editor-table border-collapse w-full my-6\" style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Hạng giải</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Chi tiết phần thưởng</strong></p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Nhất</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 02 TGG 800 QH</p><p style=\"text-align: justify;\">- 10 Điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Nhì</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 01 TGG 600 QH</p><p style=\"text-align: justify;\">- 01 TGG 500 QH (áp dụng cho Trang phục ≥ 599 QH)</p><p style=\"text-align: justify;\">- 08 điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Ba</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 01 TGG 400 QH</p><p style=\"text-align: justify;\">- 01 TGG 500 QH (áp dụng cho Trang phục ≥ 599 QH)</p><p style=\"text-align: justify;\">- 05 Điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải Tư</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 01 TGG 200 QH</p><p style=\"text-align: justify;\">- 01 TGG 400 QH (áp dụng cho Trang phục ≥ 599 QH)</p><p style=\"text-align: justify;\">- 03 điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải 5 đến 8</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- 01 TGG 150 QH</p><p style=\"text-align: justify;\">- 01 TGG 300 QH (áp dụng cho Trang phục ≥ 599 QH)</p><p style=\"text-align: justify;\">- 01 Điểm quay thưởng tại website của Garena</p></td></tr><tr><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\"><strong>Giải phụ</strong></p></td><td class=\"border border-gray-300 p-2 min-w-[100px]\" colspan=\"1\" rowspan=\"1\"><p style=\"text-align: justify;\">- Trao tặng <strong>05</strong> bộ Huy chương lưu niệm</p></td></tr></tbody></table><p style=\"text-align: 