  `tin_tuc_id` bigint(20) NOT NULL COMMENT 'FK → tin_tuc.id',
  `duong_dan` varchar(1000) NOT NULL COMMENT 'Path ảnh lưu trữ',
  `ten_file_goc` varchar(500) DEFAULT NULL COMMENT 'Tên file gốc khi upload',
  `mo_ta` varchar(500) DEFAULT NULL COMMENT 'Alt text cho ảnh (SEO)',
  `thu_tu` int(11) NOT NULL DEFAULT 0 COMMENT 'Thứ tự trong gallery',
  `ngay_upload` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ảnh gallery của bài tin tức';

