--
-- Cấu trúc bảng cho bảng `url_redirect`
--

CREATE TABLE `url_redirect` (
  `id` bigint(20) NOT NULL,
  `url_cu` varchar(1000) NOT NULL COMMENT 'Path cũ, không có dấu / đầu',
  `url_moi` varchar(1000) NOT NULL COMMENT 'Path mới, không có dấu / đầu',
  `kieu` int(11) NOT NULL DEFAULT 301 COMMENT '301 = permanent | 302 = temporary',
  `ly_do` varchar(500) DEFAULT NULL COMMENT 'Ghi chú lý do redirect',
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lưu redirect khi đổi tên danh mục làm thay đổi full_path_slug';

