--
-- Cấu trúc bảng cho bảng `van_ban`
--

CREATE TABLE `van_ban` (
  `id` bigint(20) NOT NULL,
  `so_hieu` varchar(100) DEFAULT NULL COMMENT 'Ví dụ: "12/KH-ĐTN", "05/QĐ-HSV"',
  `trich_yeu` varchar(1000) NOT NULL COMMENT 'Tiêu đề / trích yếu nội dung',
  `slug` varchar(500) NOT NULL COMMENT 'Slug sinh từ so_hieu + trich_yeu',
  `full_url_path` varchar(1000) NOT NULL COMMENT 'Full path URL: "doan-thanh-nien/ke-hoach/.../slug"',
  `loai_van_ban` enum('KE_HOACH','CONG_VAN','QUYET_DINH','THONG_BAO','BAO_CAO','HUONG_DAN','BIEN_BAN','TO_TRINH','KHAC') NOT NULL COMMENT 'Loại văn bản',
  `chuyen_muc_id` bigint(20) DEFAULT NULL COMMENT 'FK → chuyen_muc.id (nullable)',
  `co_quan_ban_hanh` varchar(200) DEFAULT NULL COMMENT 'Ví dụ: "Đoàn TN Trường ĐH Kiên Giang"',
  `nguoi_ky` varchar(200) DEFAULT NULL COMMENT 'Ví dụ: "Nguyễn Văn A — Bí thư"',
  `ngay_ban_hanh` date DEFAULT NULL COMMENT 'Ngày ký ban hành chính thức',
  `ngay_hieu_luc` date DEFAULT NULL COMMENT 'Ngày bắt đầu có hiệu lực',
  `ngay_het_han` date DEFAULT NULL COMMENT 'NULL = còn hiệu lực vĩnh viễn',
  `hoat_dong_id` varchar(50) DEFAULT NULL COMMENT 'FK mềm → hoat_dong.ma_hoat_dong (enforce ở Service)',
  `trang_thai` enum('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT' COMMENT 'PUBLISHED = bất biến (VB-001)',
  `hieu_luc` enum('CON_HIEU_LUC','HET_HIEU_LUC','CHUA_HIEU_LUC') NOT NULL DEFAULT 'CON_HIEU_LUC',
  `nguoi_dang` varchar(50) NOT NULL COMMENT 'FK mềm → tai_khoan.username',
  `don_vi_dang` varchar(100) DEFAULT NULL COMMENT 'Tên đơn vị đăng bài',
  `luot_xem` int(11) NOT NULL DEFAULT 0,
  `luot_tai` int(11) NOT NULL DEFAULT 0,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Kho văn bản / kế hoạch / công văn — PUBLISHED bất biến';

--
-- Đang đổ dữ liệu cho bảng `van_ban`
--

INSERT INTO `van_ban` (`id`, `so_hieu`, `trich_yeu`, `slug`, `full_url_path`, `loai_van_ban`, `chuyen_muc_id`, `co_quan_ban_hanh`, `nguoi_ky`, `ngay_ban_hanh`, `ngay_hieu_luc`, `ngay_het_han`, `hoat_dong_id`, `trang_thai`, `hieu_luc`, `nguoi_dang`, `don_vi_dang`, `luot_xem`, `luot_tai`, `is_deleted`, `created_at`, `updated_at`) VALUES
